import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import { Card, Container, Row, Col, Form, Alert } from "react-bootstrap";
import "chartist/dist/chartist.min.css";

/* ===================== STYLE ===================== */
const themeStyle = `
.chart-scroll { overflow-x: auto; overflow-y: hidden; }
.history-header {
  background: linear-gradient(87deg, #5e72e4 0, #825ee4 100%) !important;
  border-radius: 8px 8px 0 0 !important;
  padding: 20px !important;
}
.history-header .card-title { color: white !important; margin: 0 !important; font-weight: bold; font-size: 1.25rem; }
.form-select {
  border-radius: 12px !important;
  padding: 8px 15px !important;
  border: 1px solid #e9ecef !important;
  background-color: #ffffff !important;
  font-size: 14px !important;
  color: #525f7f !important;
}
.form-label {
  font-weight: 700;
  color: #5e72e4;
  text-transform: uppercase;
  font-size: 0.75rem;
  letter-spacing: 0.025em;
  margin-bottom: 8px;
}
.card {
  border: none !important;
  box-shadow: 0 0 2rem 0 rgba(136, 152, 170, 0.15) !important;
  margin-bottom: 30px !important;
  border-radius: 0.75rem !important;
}
.no-data-card {
  border: 2px dashed #e9ecef !important;
  background-color: #f8f9fe !important;
}
`;

/* ===================== CONSTANT ===================== */
const CAMERA_MAP = {
  CAM01: "วิศวะ",
  CAM02: "วิทยาศาสตร์",
  CAM03: "ศิลปศาสตร์",
  CAM04: "PKY",
};

/* ===================== UTIL FUNCTION ===================== */
const averageByHour = (labels, series) => {
  const bucket = {};
  labels.forEach((label, idx) => {
    const hour = label.split(":")[0]; 
    const key = `${hour.padStart(2, '0')}:00`;

    if (!bucket[key]) {
      bucket[key] = { sum: 0, count: 0 };
    }
    bucket[key].sum += series[idx];
    bucket[key].count += 1;
  });

  const newLabels = [];
  const newSeries = [];

  // สร้างช่วงเวลา 07:00 - 22:00 แบบ Fix เพื่อป้องกันเลขหายกรณีบางชั่วโมงไม่มีข้อมูล
  for (let i = 7; i <= 22; i++) {
    const hourStr = `${i.toString().padStart(2, '0')}:00`;
    newLabels.push(hourStr);
    if (bucket[hourStr]) {
      newSeries.push(Math.round(bucket[hourStr].sum / bucket[hourStr].count));
    } else {
      newSeries.push(0); // ถ้าไม่มีข้อมูลชั่วโมงนั้นให้เป็น 0
    }
  }

  return { labels: newLabels, series: newSeries };
};

/* ===================== COMPONENT ===================== */
function History() {
  const currentYearCE = new Date().getFullYear();
  const currentYearBE = currentYearCE + 543;

  const [selectedDay, setSelectedDay] = useState(new Date().getDate().toString());
  const [selectedMonth, setSelectedMonth] = useState((new Date().getMonth() + 1).toString().padStart(2, "0"));
  const [selectedYearBE, setSelectedYearBE] = useState(currentYearBE.toString());
  const [cameraId, setCameraId] = useState("CAM01");

  const [chartState, setChartState] = useState({ labels: [], series: [[]] });
  const [isLoaded, setIsLoaded] = useState(false);

  const START_TIME = "07:00";
  const END_TIME = "22:00";

  const monthsThai = [
    { val: "01", name: "มกราคม" }, { val: "02", name: "กุมภาพันธ์" },
    { val: "03", name: "มีนาคม" }, { val: "04", name: "เมษายน" },
    { val: "05", name: "พฤษภาคม" }, { val: "06", name: "มิถุนายน" },
    { val: "07", name: "กรกฎาคม" }, { val: "08", name: "สิงหาคม" },
    { val: "09", name: "กันยายน" }, { val: "10", name: "ตุลาคม" },
    { val: "11", name: "พฤศจิกายน" }, { val: "12", name: "ธันวาคม" },
  ];

  const yearsBE = Array.from({ length: 2 }, (_, i) => (currentYearBE - i).toString());
  const daysArray = Array.from({ length: 31 }, (_, i) => (i + 1).toString());

  const handleSearch = async () => {
    setIsLoaded(false);
    const yearCE = parseInt(selectedYearBE) - 543;
    const formattedDate = `${yearCE}-${selectedMonth}-${selectedDay.padStart(2, "0")}`;
    const API_BASE = "http://localhost:3001";

    try {
      const res = await fetch(
        `${API_BASE}/api/history?cameraId=${cameraId}&date=${formattedDate}&startTime=${START_TIME}&endTime=${END_TIME}`
      );
      const result = await res.json();

      if (result && result.labels && result.labels.length > 0) {
        const averaged = averageByHour(result.labels, result.series[0]);
        setChartState({
          labels: averaged.labels,
          series: [averaged.series],
        });
      } else {
        setChartState({ labels: [], series: [[]] });
      }
    } catch (err) {
      console.error(err);
      setChartState({ labels: [], series: [[]] });
    } finally {
      setIsLoaded(true);
    }
  };

  useEffect(() => {
    handleSearch();
  }, [selectedDay, selectedMonth, selectedYearBE, cameraId]);

  const barChartOptions = {
    height: "400px",
    axisX: { 
        showGrid: false, 
        offset: 60
    },
    axisY: { 
        onlyInteger: true, 
        low: 0 
    },
    fullWidth: true,
    // เพิ่มบรรทัดนี้เพื่อป้องกันการข้าม Label
    chartPadding: { top: 40, right: 15, bottom: 0, left: 10 }
  };

  const drawBarLabels = (data) => {
    if (data.type === "bar") {
      // ปรับแต่งสี: ถ้าเกิน 20 เป็นสีแดง ต่ำกว่าเป็นสีเขียว
      const color = data.value.y > 20 ? "#f5365c" : "#2dce89";
      
      data.element.attr({ 
        style: `stroke: ${color}; stroke-width: 25px;` 
      });

      // ส่วนการวาดตัวเลขบนแท่ง
      data.group.elem("text", {
        x: data.x2,
        y: data.y2 - 12, // ขยับขึ้นเหนือแท่ง
        style: "font-size:12px; fill:#333; font-weight:bold; text-anchor:middle; font-family: sans-serif;"
      }).text(data.value.y);
    }
  };

  return (
    <Container fluid className="py-4">
      <style>{themeStyle}</style>
      <Row>
        <Col md="12">
          <Card>
            <Card.Header className="history-header">
              <Card.Title as="h4">สถิติปริมาณคนรายชั่วโมง (07:00 - 22:00)</Card.Title>
            </Card.Header>
            <Card.Body className="px-4 py-4">
              <Row className="align-items-end g-3">
                <Col md="4">
                  <Form.Group>
                    <Form.Label className="form-label">เลือกสถานที่ (ป้ายรถเมล์)</Form.Label>
                    <Form.Select value={cameraId} onChange={(e) => setCameraId(e.target.value)}>
                      {Object.entries(CAMERA_MAP).map(([key, val]) => (
                        <option key={key} value={key}>{val}</option>
                      ))}
                    </Form.Select>
                  </Form.Group>
                </Col>
                <Col md="8">
                  <Form.Label className="form-label">เลือกวันที่</Form.Label>
                  <div className="d-flex gap-2">
                    <Form.Select value={selectedDay} onChange={(e) => setSelectedDay(e.target.value)}>
                      {daysArray.map((d) => <option key={d} value={d}>{d}</option>)}
                    </Form.Select>
                    <Form.Select value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)}>
                      {monthsThai.map((m) => <option key={m.val} value={m.val}>{m.name}</option>)}
                    </Form.Select>
                    <Form.Select value={selectedYearBE} onChange={(e) => setSelectedYearBE(e.target.value)}>
                      {yearsBE.map((y) => <option key={y} value={y}>{y}</option>)}
                    </Form.Select>
                  </div>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {isLoaded && chartState.labels.length > 0 && (
        <Row>
          <Col md="12">
            <Card>
              <Card.Header className="bg-transparent border-0 pt-4 px-4">
                <h6 className="text-uppercase text-muted mb-1">Performance</h6>
                <h2 className="mb-0 h4 font-weight-bold text-primary">
                  กราฟสถิติ : {CAMERA_MAP[cameraId]} (รายชั่วโมง)
                </h2>
              </Card.Header>
              <Card.Body className="px-4">
                <div className="chart-scroll">
                  {/* กำหนดความกว้างให้พอดีกับหน้าจอ ไม่กว้างเกินไปจนเลขหาย */}
                  <div style={{ width: "100%", minWidth: "800px", height: "450px" }}>
                    <ChartistGraph
                      data={{ labels: chartState.labels, series: chartState.series }}
                      type="Bar"
                      options={barChartOptions}
                      listener={{ draw: drawBarLabels }}
                    />
                  </div>
                </div>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}

      {isLoaded && chartState.labels.length === 0 && (
        <Row>
          <Col md="12">
            <Card className="no-data-card py-5 text-center">
              <Card.Body>
                <div className="mb-3"><span style={{ fontSize: "48px" }}>📅</span></div>
                <h3 className="text-muted font-weight-bold">ไม่พบข้อมูลสถิติ</h3>
                <p className="text-muted mb-0">ไม่พบข้อมูลของสถานที่ <b>{CAMERA_MAP[cameraId]}</b></p>
                <p className="text-muted">ในวันที่ <b>{selectedDay} {monthsThai.find(m => m.val === selectedMonth)?.name} {selectedYearBE}</b></p>
                <Alert variant="warning" className="d-inline-block mt-3">กรุณาลองเลือกวันที่อื่น</Alert>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}
    </Container>
  );
}

export default History;
